OutputTag<Event> lateTag = new OutputTag<Event>("late-events"){};

// 1. 定义 WatermarkStrategy
WatermarkStrategy<Event> ws = WatermarkStrategy
    .<Event>forBoundedOutOfOrderness(Duration.ofSeconds(5))
    .withTimestampAssigner((event, recordTs) -> event.eventTimeMs)
    .withIdleness(Duration.ofMinutes(1));  // 空分区跳过，防全局卡死

// 2. Source 绑定 WatermarkStrategy
DataStream<Event> src = env
    .fromSource(kafkaSource, WatermarkStrategy.forMonotonousTimestamps(), "raw")
    .assignTimestampsAndWatermarks(ws);

// 3. 窗口聚合 + 两层迟到补偿
SingleOutputStreamOperator<WindowResult> result = src
    .keyBy(Event::userId)
    .window(TumblingEventTimeWindows.of(Time.minutes(1)))
    .allowedLateness(Time.minutes(10))    // 状态保留 10 分钟，迟到事件触发增量重算
    .sideOutputLateData(lateTag)          // 超过 10 分钟的事件走侧输出
    .aggregate(new CountAgg(), new WindowResultFunction());

// 4. 正常结果写主 sink
result.sinkTo(buildMainSink());

// 5. 迟到数据写独立 topic，由离线 Spark 每天补算
result.getSideOutput(lateTag)
    .sinkTo(KafkaSink.<Event>builder()
        .setBootstrapServers(brokers)
        .setRecordSerializer(
            KafkaRecordSerializationSchema.builder()
                .setTopic("late-events")
                .setValueSerializationSchema(new EventSerializer())
                .build())
        .build());

// 6. 监控：注册 watermark lag metric
result.getSideOutput(lateTag)
    .map(e -> 1)
    .addSink(new RichSinkFunction<Integer>() {
        private transient Counter lateCounter;
        @Override
        public void open(Configuration parameters) {
            lateCounter = getRuntimeContext()
                .getMetricGroup()
                .counter("late_events_count");
        }
        @Override
        public void invoke(Integer value, Context ctx) {
            lateCounter.inc();
        }
    });
